    const line = i => { const t = B.teams[i]; return `<tr><td>${esc(nm[i])}</td><td>${t.g}</td><td>${t.a}</td><td>${t.sh}</td><td>${t.sog}</td><td>${t.pipe}</td><td>${t.wide}</td><td>${t.bl}</td><td>${t.sv}</td><td>${t.to}</td><td>${t.ct}</td><td>${t.gb}</td><td>${t.fw}</td><td>${t.clearMade}/${t.clearAtt}</td><td>${t.pen}</td></tr>`; };
