    document.querySelectorAll('[data-game]').forEach(b => { b.onclick = () => { openReplay(current(), Number(b.dataset.game)); render(); }; });
    const gn = $('gameNo'); if (gn) gn.onchange = () => { const X = current(), i = Math.max(0, Math.min(X.r.record.requestedGames - 1, Number(gn.value) - 1)); if (X.r.games.find(x => x.index === i)) { openReplay(X, i); render(); } };
