  function paintProgress() { const el = $('prog'); if (!el) return; const p = ST.progress; el.innerHTML = p ? `<div class="sub" style="margin:0 0 4px">${esc(p.label)}: ${p.done.toLocaleString()} of ${p.total.toLocaleString()} games completed</div><div class="bar"><i style="width:${(100 * p.done / Math.max(1, p.total)).toFixed(1)}%"></i></div>` : ''; }
  function render() {
    if (ST.player) { ST.player.stop(); }
    const body = ST.tab === 'overview' ? overviewHtml() : ST.tab === 'players' ? playersHtml() : ST.tab === 'lineups' ? lineupsHtml() : ST.tab === 'inputs' ? inputsHtml() : replayHtml();
    const active = document.activeElement && document.activeElement.dataset ? document.activeElement.dataset.ov : null;
    $('app').innerHTML = headerHtml() + `<div class="tabs" role="tablist">${TABS.map(([k, l]) => `<button class="tab${ST.tab === k ? ' on' : ''}" role="tab" data-tab="${k}">${l}</button>`).join('')}</div>` + body;
    paintProgress(); bind(); bindTips(); if (ST.tab === 'replay') mountReplay();
    if (active) { const el = document.querySelector(`[data-ov="${active}"]`); if (el) { el.focus(); const v = el.value; el.value = ''; el.value = v; } }
  }
