    const sd = $('seed'); if (sd) sd.onchange = () => { ST.seed = Math.max(1, Math.floor(Number(sd.value)) || 1); }; const run = $('run'); if (run) run.onclick = runMatchup; const can = $('cancel'); if (can) can.onclick = () => { ST.cancel = true; };
    on('[data-ov]', el => { el.onchange = () => { const k = el.dataset.ov; if (el.value === '') delete ST.ov[k]; else ST.ov[k] = el.value; render(); }; }); on('[data-reset]', b => { b.onclick = () => { delete ST.ov[b.dataset.reset]; render(); }; }); const ra = $('resetAll'); if (ra) ra.onclick = () => { ST.ov = {}; render(); };
    on('[data-rot]', b => { b.onclick = () => { toggleRot(b.dataset.rot, b.dataset.j); render(); }; }); on('[data-share]', el => { el.onchange = () => { ST.rotation.lines[Number(el.dataset.share)].share = Number(el.value) / 100; render(); }; });
    const al = $('addLine'); if (al) al.onclick = () => { ST.rotation.lines.push({ players: [], share: 0.2 }); render(); }; const dl = $('dropLine'); if (dl) dl.onclick = () => { ST.rotation.lines.pop(); render(); };
    const sr = $('saveRot'); if (sr) sr.onclick = () => { const nm = ($('rotName').value || '').trim() || `Rotation ${ST.tested.length + 1}`; ST.tested.push({ name: nm, rotation: JSON.parse(JSON.stringify(ST.rotation)) }); render(); }; const rr = $('resetRot'); if (rr) rr.onclick = () => { ST.rotation = JSON.parse(JSON.stringify(ST.fixtureRotation)); render(); };
    on('[data-load]', b => { b.onclick = () => { ST.rotation = JSON.parse(JSON.stringify(ST.tested[Number(b.dataset.load)].rotation)); render(); }; }); on('[data-del]', b => { b.onclick = () => { ST.tested.splice(Number(b.dataset.del), 1); render(); }; }); const rc = $('runCmp'); if (rc) rc.onclick = runCompare;
